-- PASS: facts generated by procedural Lua, symbols from strings, runtime API.
relation edge(3)
relation hazard(1)
relation traversable(2)

fact edge(:node1, :node2, :dirt)
fact edge(:node2, :node3, :stone)
fact edge(:node2, :node4, :lava)
fact edge(:node2, :node5, :acid)

local blocked = {lava = true, acid = true}
for terrain in pairs(blocked) do
    fact hazard(symbol(terrain))
end

rule traversable(?from, ?to) :-
    edge(?from, ?to, ?terrain),
    not hazard(?terrain)

local function check(expected)
    local seen, count = {}, 0
    for m in query traversable(:node2, ?to) do
        assert(expected[m.to], "unexpected traversable destination")
        seen[m.to] = true
        count = count + 1
    end
    local n = 0
    for dest in pairs(expected) do
        assert(seen[dest], "missing traversable destination")
        n = n + 1
    end
    assert(count == n)
end

check({[:node3] = true})
retract hazard(:lava)
check({[:node3] = true, [:node4] = true})

logic.add(logic.global, "hazard", :stone)
check({[:node4] = true})
logic.retract(logic.global, "hazard", :stone)
check({[:node3] = true, [:node4] = true})
print("PASS 06_procedural_fact_generation")
